head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil16507";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16507.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 3개다(tx_fn_Search, tx_fn_SearchRspnDetail, tx_fn_SearchChrgDetail) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_47_onclick
 * @description img_47 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_47_onclick = async function(e){
    try {
        await scwin.findCompany()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16507.img_47_onclick' }); }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description btn_Search 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16507.btn_Search_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        await scwin.search();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16507.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_educationList_oncellclick
 * @description grd_educationList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_educationList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_educationList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_educationList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_SearchRspnDetail (조건 미해석) · fn_SearchChrgDetail (조건 미해석) */
        if (r["chrgTpNm"] === '공시책임자') { await scwin.searchRspnDetail(r["disclsEduApplSeq"], r["chrgTpCd"], r["disclsBzChrgAssgnDd"], r["seq"], r["isurCd"], "N"); return; }
        await scwin.searchChrgDetail(r["disclsEduApplSeq"], r["seq"], r["isurCd"], "N"); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_educationList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_108_onclick
 * @description krxpage_pagenavigator_108 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_108_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_SearchReq').set('pageIndex', pi);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil16507.krxpage_pagenavigator_108_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "제출 주소를 찾지 못했습니다(전환 미완) — educationStaff.do"
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — educationStaff.do", unresolved: "action:educationStaff.do" };
};

/**
 * @method
 * @name tx_fn_SearchRspnDetail
 * @description Search Rspn Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_SearchRspnDetail = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "제출 주소를 찾지 못했습니다(전환 미완) — eduRspnStaff.do"
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — eduRspnStaff.do", unresolved: "action:eduRspnStaff.do" };
};

/**
 * @method
 * @name tx_fn_SearchChrgDetail
 * @description Search Chrg Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_SearchChrgDetail = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "제출 주소를 찾지 못했습니다(전환 미완) — eduChrgStaff.do"
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — eduChrgStaff.do", unresolved: "action:eduChrgStaff.do" };
};

/**
 * @method
 * @name grd_educationList_fmt_chrgTpNm
 * @description grd education List fmt chrg Tp Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_educationList_fmt_chrgTpNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_educationList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "chrgTpNm") ?? '') : '');
        if (v === '공시책임자') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: chrgTpNm (expression)'), String(data ?? '')) + '</a>'; }
        return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: chrgTpNm (expression)'), String(data ?? '')) + '</a>';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_educationList.chrgTpNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const frm = (document.eduForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'searchSaveEducationList');
    frm.action = 'educationStaff.do';
    $c.util.getComponent('dma_SearchReq').set('SCREN_PROCES_TP_CD', "01");
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name searchRspnDetail
 * @description search Rspn Detail 처리
 * @param {*} disclsEduApplSeq disclsEduApplSeq
 * @param {String} chrgTpCd chrgTpCd
 * @param {String} disclsBzChrgAssgnDd disclsBzChrgAssgnDd
 * @param {*} seq seq
 * @param {String} isurCd isurCd
 * @param {String} editAvailYn editAvailYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchRspnDetail = async function (disclsEduApplSeq, chrgTpCd, disclsBzChrgAssgnDd, seq, isurCd, editAvailYn) {
    const frm = (document.eduDetailForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'findEducationStaffResponsibilityDetail');
    $c.util.getComponent('dma_SearchReq').set('disclsEduApplSeq', disclsEduApplSeq);
    $c.util.getComponent('dma_SearchReq').set('chrgTpCd', chrgTpCd);
    $c.util.getComponent('dma_SearchReq').set('disclsBzChrgAssgnDd', disclsBzChrgAssgnDd);
    $c.util.getComponent('dma_SearchReq').set('seq', seq);
    $c.util.getComponent('dma_SearchReq').set('txtisurCd', isurCd);
    $c.util.getComponent('dma_SearchReq').set('editAvailYn', editAvailYn);
    frm.action = 'eduRspnStaff.do';
    $c.util.getComponent('dma_SearchReq').set('SCREN_PROCES_TP_CD', "01");
    await scwin.tx_fn_SearchRspnDetail();
};

/**
 * @method
 * @name searchChrgDetail
 * @description search Chrg Detail 처리
 * @param {*} disclsEduApplSeq disclsEduApplSeq
 * @param {*} seq seq
 * @param {String} isurCd isurCd
 * @param {String} editAvailYn editAvailYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchChrgDetail = async function (disclsEduApplSeq, seq, isurCd, editAvailYn) {
    const frm = (document.eduDetailForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'findEducationStaffChargeDetail');
    $c.util.getComponent('dma_SearchReq').set('disclsEduApplSeq', disclsEduApplSeq);
    $c.util.getComponent('dma_SearchReq').set('seq', seq);
    $c.util.getComponent('dma_SearchReq').set('txtisurCd', isurCd);
    $c.util.getComponent('dma_SearchReq').set('editAvailYn', editAvailYn);
    frm.action = 'eduChrgStaff.do';
    $c.util.getComponent('dma_SearchReq').set('SCREN_PROCES_TP_CD', "01");
    await scwin.tx_fn_SearchChrgDetail();
};

/**
 * @method
 * @name findCompany
 * @description find Company 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findCompany = async function () {
    const corpSearchURL = '/jldfil00033/jldfil00033.xml';
    scwin.setCorpInfo_recv(await $c.win.openPopup(corpSearchURL, { id: "corpWin", scrollbars: false, resizable: false, width: "600", height: "510", type: "pageFramePopup" }, { method: "loadInitPage" }));
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    $c.util.getComponent('dma_SearchReq').set('txtisurCd', isurCd);
    $c.util.getComponent('dma_SearchReq').set('txtfssUnqNo', fssUnqNo);
    $c.util.getComponent("ipt_txtcomNm").setValue(comNm);
    $c.util.getComponent('dma_SearchReq').set('tgtIsuSrtCd', repIsuSrtCd);
    $c.util.getComponent('dma_SearchReq').set('chkPop', 'Y');
};

/**
 * @method
 * @name setCorpInfo_recv
 * @description 팝업 회신 수신 — 팝업이 남긴 인자를 as-is 함수 인자 순서로 펼쳐 넘긴다.
 * @param {*} r r
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo_recv = function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } };
